static pthread_mutex_t g_up_lock = PTHREAD_MUTEX_INITIALIZER;

/* ONE TLS STACK IN THIS PROCESS AT A TIME.
 *
 * https_get_text and https_download each create and destroy their own
 * sceNetPoolCreate/sceSslInit/sceHttpInit triple, and nothing used to stop both from existing at
 * once. This file's own probe table records what that costs: a reply carrying net=3000 ssl=4
 * http=260 - "a SECOND sceNet/sceSsl/sceHttp stack initialised in a process where the upstream
 * worker already holds one" - failing on every host, example.com included. The upstream worker
 * holds a stack for as long as a release check takes, which on a cold check is seconds and on a
 * failing one is up to a minute, and "open the Payloads panel, then press Update" puts a download
 * squarely inside that window. It is the commonest thing an owner does with this drawer.
 *
 * A mutex rather than a queue: a release check and a download are both already on worker threads,
 * so waiting is free, and the alternative is the failure above with no way to tell it from a dead
 * host. */
static pthread_mutex_t g_tls_lock = PTHREAD_MUTEX_INITIALIZER;

/* DOES TLS WORK IN THIS PROCESS? 0 nothing tried yet, 1 yes, -1 no.
 *
 * Reported in /api/payloads so the page can stop offering a download this console cannot make.
 * MEASURED on the owner's PS4 at 3.98.4: every attempt answers 0x8095f006, sceHttpsLoadCert
 * included, with the net and SSL sysmodules loaded and sceNetInit() returning 0 - so on that
 * console the answer is a settled no, and the owner pressing Update deserves to be told that
 * before the press rather than shown a hex code after it.
 *
 * THREE STATES, BECAUSE TWO WOULD BE A LIE. "Not tried yet" is the state a freshly loaded payload
 * is in, and reporting it as failure would send every PS4 owner to look for a PC they do not need
 * - the PS5 answers these questions perfectly well and must go on doing so.
 *
 * Only a TRANSPORT failure counts. An HTTP 404 or a rate limit is the far end talking, which
 * proves TLS worked; sceSslInit refusing, or a send that never gets a status, is this console. */
static volatile int g_tls_state;

static int pms_ssl_accept_cb(void *a, void *b, void *c, int d) {
    (void)a; (void)b; (void)c; (void)d;
    return 0;
}

/* Say the same thing three ways, because one of them is not enough on every console.
 *
 * MEASURED: this lane works on the PS5 with the SSL callback alone and fails on the PS4 with
 * 0x8095f006 - the unknown-CA code in the libSsl verification family, which means the handshake
 * happened and the chain was rejected. The callback's whole body is `return 0`, so the lane's
 * intent has always been "do not verify, and check the release's own sha256 instead" - the digest
 * arrives from a different host than the bytes, which is what makes it worth having. The PS4's
 * callback signature takes five arguments where ours takes four, and whether it is consulted for
 * an unknown CA is not a thing to settle by reading.
 *
 * 0x3F is the whole family: server-verify 0x01, client-verify 0x02, name check 0x04, not-after
 * 0x08, not-before 0x10, known-CA 0x20. Disabling only 0x01 leaves four that fail identically,
 * which the probe table above records.
 *
 * Every call is logged with its return code. "It returned something and we carried on" is how the
 * last attempt at this ended up with nothing to read. */
static void tls_relax(int httpctx, int tmpl, const char *who) {
    int lc = sceHttpsLoadCert(httpctx, 0, NULL, NULL, NULL);
    int dv = sceHttpsDisableOption(tmpl, 0x3F);
    int cb = sceHttpsSetSslCallback(tmpl, (void *)pms_ssl_accept_cb, NULL);
    if (lc < 0 || dv < 0 || cb < 0)
        ilog("tls(%s): ctx http=%d ssl=%d - loadcert=0x%x disableverify=0x%x sslcb=0x%x",
             who ? who : "?", httpctx, tmpl, (unsigned)lc, (unsigned)dv, (unsigned)cb);
}

static void tls_verdict(int ok) {
    int was = g_tls_state;
    g_tls_state = ok ? 1 : -1;
    if (was != g_tls_state)
        ilog("tls: this process %s reach an https host", ok ? "can" : "cannot");
}

static ssize_t write_all_checked(int fd, const char *buf, size_t len) {
    size_t off = 0;
    while (off < len) {
        ssize_t k = write(fd, buf + off, len - off);
        if (k < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (k == 0) return -1;              /* no progress: out of space, or the fd went away */
        off += (size_t)k;
    }
    return (ssize_t)off;
}

static int ver_cmp(const char *a, const char *b) {
    for (;;) {
        long x = 0, y = 0;
        if (a && *a) { x = strtol(a, (char **)&a, 10); if (*a == '.') a++; }
        if (b && *b) { y = strtol(b, (char **)&b, 10); if (*b == '.') b++; }
        if (x != y) return x > y ? 1 : -1;
        if ((!a || !*a) && (!b || !*b)) return 0;
    }
}

static void pms_sha256_init(pms_sha256_t *c) {
    c->h[0] = 0x6a09e667u; c->h[1] = 0xbb67ae85u; c->h[2] = 0x3c6ef372u; c->h[3] = 0xa54ff53au;
    c->h[4] = 0x510e527fu; c->h[5] = 0x9b05688cu; c->h[6] = 0x1f83d9abu; c->h[7] = 0x5be0cd19u;
    c->bits = 0;
    c->n = 0;
}

static void pms_sha256_block(pms_sha256_t *c, const unsigned char *p) {
    unsigned int w[64], a, b2, d, e, f, g, hh, cc, t1, t2;
    int i;
    for (i = 0; i < 16; i++)
        w[i] = ((unsigned int)p[i * 4] << 24) | ((unsigned int)p[i * 4 + 1] << 16) |
               ((unsigned int)p[i * 4 + 2] << 8) | (unsigned int)p[i * 4 + 3];
    for (i = 16; i < 64; i++) {
        unsigned int s0 = PMS_ROR(w[i - 15], 7) ^ PMS_ROR(w[i - 15], 18) ^ (w[i - 15] >> 3);
        unsigned int s1 = PMS_ROR(w[i - 2], 17) ^ PMS_ROR(w[i - 2], 19) ^ (w[i - 2] >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }
    a = c->h[0]; b2 = c->h[1]; cc = c->h[2]; d = c->h[3];
    e = c->h[4]; f = c->h[5]; g = c->h[6]; hh = c->h[7];
    for (i = 0; i < 64; i++) {
        unsigned int S1 = PMS_ROR(e, 6) ^ PMS_ROR(e, 11) ^ PMS_ROR(e, 25);
        unsigned int ch = (e & f) ^ ((~e) & g);
        unsigned int S0 = PMS_ROR(a, 2) ^ PMS_ROR(a, 13) ^ PMS_ROR(a, 22);
        unsigned int mj = (a & b2) ^ (a & cc) ^ (b2 & cc);
        t1 = hh + S1 + ch + PMS_SHA_K[i] + w[i];
        t2 = S0 + mj;
        hh = g; g = f; f = e; e = d + t1;
        d = cc; cc = b2; b2 = a; a = t1 + t2;
    }
    c->h[0] += a; c->h[1] += b2; c->h[2] += cc; c->h[3] += d;
    c->h[4] += e; c->h[5] += f;  c->h[6] += g;  c->h[7] += hh;
}

static void pms_sha256_update(pms_sha256_t *c, const void *data, size_t len) {
    const unsigned char *p = (const unsigned char *)data;
    c->bits += (unsigned long long)len * 8ULL;
    while (len) {
        size_t room = 64 - c->n;
        size_t take = (len < room) ? len : room;
        memcpy(c->buf + c->n, p, take);
        c->n += take;
        p += take;
        len -= take;
        if (c->n == 64) { pms_sha256_block(c, c->buf); c->n = 0; }
    }
}

static void pms_sha256_final(pms_sha256_t *c, char *hex, size_t hexsz) {
    unsigned long long bits = c->bits;         /* the padding must not change the length */
    unsigned char pad = 0x80;
    int i;
    pms_sha256_update(c, &pad, 1);
    pad = 0;
    while (c->n != 56) pms_sha256_update(c, &pad, 1);
    for (i = 0; i < 8; i++) c->buf[56 + i] = (unsigned char)(bits >> (56 - 8 * i));
    pms_sha256_block(c, c->buf);
    c->n = 0;
    if (hex && hexsz >= 65) {
        static const char *hx = "0123456789abcdef";
        for (i = 0; i < 8; i++) {
            unsigned int v = c->h[i];
            hex[i * 8 + 0] = hx[(v >> 28) & 15]; hex[i * 8 + 1] = hx[(v >> 24) & 15];
            hex[i * 8 + 2] = hx[(v >> 20) & 15]; hex[i * 8 + 3] = hx[(v >> 16) & 15];
            hex[i * 8 + 4] = hx[(v >> 12) & 15]; hex[i * 8 + 5] = hx[(v >> 8) & 15];
            hex[i * 8 + 6] = hx[(v >> 4) & 15];  hex[i * 8 + 7] = hx[v & 15];
        }
        hex[64] = 0;
    }
}

#undef PMS_ROR

/* Hex sha256 of a file. Returns 0 on success. */
static int sha256_file(const char *path, char *hex, size_t hexsz) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    char *buf = (char *)malloc(256 * 1024);
    if (!buf) { close(fd); return -1; }
    pms_sha256_t c;
    pms_sha256_init(&c);
    for (;;) {
        ssize_t r = read(fd, buf, 256 * 1024);
        if (r < 0) {
            if (errno == EINTR) continue;
            free(buf);
            close(fd);
            return -1;
        }
        if (r == 0) break;
        pms_sha256_update(&c, buf, (size_t)r);
    }
    free(buf);
    close(fd);
    pms_sha256_final(&c, hex, hexsz);
    return 0;
}

static int host_unreachable_here(const char *url) {
    return !strncmp(url, "https://github.com/", 19) ||
           !strncmp(url, "https://codeload.github.com/", 28);
}

static int https_get_text(const char *url, char *out, size_t outsz, long long *got,
                          char *err, size_t errsz) {
    int netmem = -1, sslctx = -1, httpctx = -1, tmpl = -1, conn = -1, req = -1;
    int status = -1, rc;
    long long total = 0;
    char *buf = NULL;
    if (err && errsz) err[0] = 0;
    if (out && outsz) out[0] = 0;
    if (got) *got = 0;

/* A FAILURE WITH ITS CODE, except for the two codes that mean something a sentence can say.
   0x804101e2 is libnet's RESOLVER_ETIMEDOUT: the name never resolved, so nothing was sent. It is
   not TLS and not the host - measured on a PS4, plain http://example.com/ fails the same way while
   the very same lane downloads happily from an IP address. And it is process-local: a payload
   process that cannot resolve stays that way, while another one started from the same ELF
   resolves everything. Loading the shop again is the cure, so the sentence says so.
   0x8095f0xx is the libSsl verification family - 0x8095f006 is the unknown-CA one, measured on
   the PS4 at 3.98.3 while the PS5 answered the same question in twelve seconds. That one means
   the handshake HAPPENED and the chain was refused, which is a different thing entirely from the
   resolver failing, and reading the two as one cost this project a release's worth of guessing.
   tls_relax above is the cure; the sentence is for the case where it did not take. */
#define PMS_HG_FAIL(what, code) do { \
        if (err && errsz) { \
            if ((unsigned)(code) == 0x804101e2u) \
                snprintf(err, errsz, "this console could not look up the address - " \
                                     "load the shop again"); \
            else if (((unsigned)(code) & 0xFFFFFF00u) == 0x8095F000u) \
                snprintf(err, errsz, "this console refused the site's security certificate " \
                                     "(0x%x)", (unsigned)(code)); \
            else snprintf(err, errsz, "%s=0x%x", (what), (unsigned)(code)); \
        } \
        goto done; } while (0)

    if (host_unreachable_here(url)) {
        if (err && errsz) snprintf(err, errsz, "this console cannot reach that host");
        return -1;
    }
    /* ONE STACK AT A TIME - see g_tls_lock. Taken after the cheap refusals above so a host this
       console cannot reach never waits for anything. */
    pthread_mutex_lock(&g_tls_lock);
    /* THE SIZES ARE NOT A GUESS ANY MORE, and the comment they replace said they were. The probe
       table further up this file raised these to 1 MB / 4 MB / 4 MB for its own mode>=7 branch
       with the note "a certificate chain is not small, and the sizes below were a guess" - and
       the PS4 answers 0x8095f006 from sceHttpsLoadCert, a call whose entire job is to load a
       certificate store, which is what running out of room inside libSsl would look like. The
       PS5 has been answering with 512 KB, so this can only give it more room. */
    netmem = sceNetPoolCreate("pms-get", 1024 * 1024, 0);
    if (netmem < 0) PMS_HG_FAIL("netpool", netmem);
    sslctx = sceSslInit(4 * 1024 * 1024);
    if (sslctx < 0) PMS_HG_FAIL("sslinit", sslctx);
    httpctx = sceHttpInit(netmem, sslctx, 4 * 1024 * 1024);
    if (httpctx < 0) PMS_HG_FAIL("httpinit", httpctx);
    tmpl = sceHttpCreateTemplate(httpctx, "PKG-MUTANT-SHOP", 1, 1);
    if (tmpl < 0) PMS_HG_FAIL("template", tmpl);
    sceHttpSetAutoRedirect(tmpl, 1);
    /* WHAT MAKES TLS WORK HERE, all three of them - see tls_relax. */
    tls_relax(httpctx, tmpl, "get");
    sceHttpSetConnectTimeOut(tmpl, 20 * 1000 * 1000);
    sceHttpSetSendTimeOut(tmpl, 20 * 1000 * 1000);
    sceHttpSetRecvTimeOut(tmpl, 30 * 1000 * 1000);
    conn = sceHttpCreateConnectionWithURL(tmpl, url, 1);
    if (conn < 0) PMS_HG_FAIL("connect", conn);
    req = sceHttpCreateRequestWithURL(conn, 0, url, 0);
    if (req < 0) PMS_HG_FAIL("request", req);
    /* GitHub answers 403 to a request with no User-Agent; the template sets one. Asking for the
       documented media type keeps the shape of the reply stable. */
    sceHttpAddRequestHeader(req, "Accept", "application/vnd.github+json", 0);
    rc = sceHttpSendRequest(req, NULL, 0);
    if (rc < 0) PMS_HG_FAIL("send", rc);
    rc = sceHttpGetStatusCode(req, &status);
    if (rc < 0) PMS_HG_FAIL("status", rc);
    /* THE FAR END ANSWERED, so TLS works here - even if what it answered was 404 or a rate
       limit. This is the only place that can tell "this console cannot do TLS" apart from "that
       project has nothing", and conflating the two is what sent the owner looking for a PC on a
       console that did not need one. */
    tls_verdict(1);
    buf = (char *)malloc(64 * 1024);
    if (!buf) { if (err && errsz) snprintf(err, errsz, "out of memory"); goto done; }
    for (;;) {
        int n = sceHttpReadData(req, buf, 64 * 1024);
        if (n == 0) break;
        if (n < 0) PMS_HG_FAIL("read", n);
        if (out && (size_t)total < outsz) {
            size_t room = outsz - (size_t)total - 1;
            size_t take = ((size_t)n < room) ? (size_t)n : room;
            memcpy(out + total, buf, take);
        }
        total += n;
        /* A release document is tens of kilobytes. Anything past this is not one, and reading it
           into a console's memory is not something to do politely. */
        if (total > 4LL * 1024 * 1024) break;
    }
    if (out && outsz) out[(size_t)total < outsz ? (size_t)total : outsz - 1] = 0;
    tls_verdict(1);                 /* a body arrived: the transport is fine, whatever it said */
#undef PMS_HG_FAIL
done:
    /* A failure before any status is this console's own, and that is what the page needs to
       know. Checked rather than assumed: status stays -1 until sceHttpGetStatusCode fills it. */
    if (status < 0) tls_verdict(0);
    if (got) *got = total;
    if (buf) free(buf);
    if (req >= 0) sceHttpDeleteRequest(req);
    if (conn >= 0) sceHttpDeleteConnection(conn);
    if (tmpl >= 0) sceHttpDeleteTemplate(tmpl);
    if (httpctx >= 0) sceHttpTerm(httpctx);
    if (sslctx >= 0) sceSslTerm(sslctx);
    if (netmem >= 0) sceNetPoolDestroy(netmem);
    pthread_mutex_unlock(&g_tls_lock);
    return status;
}

static int https_download(const char *url, const char *dest, char *err, size_t errsz) {
    int netmem = -1, sslctx = -1, httpctx = -1, tmpl = -1, conn = -1, req = -1;
    int status = 0, rc, fd = -1, ret = -1;
    long long have = 0, clen = -1;
    char *buf = NULL;
    struct stat stt;
    if (err && errsz) err[0] = 0;

/* THE SAME TWO SENTENCES THE CHECK SIDE HAS. This macro had neither, so a download that failed
   for a reason with a cure reported "The download did not finish (send=0x804101e2)" - the one
   sentence that says what to do existed only on the other half of the same lane. */
#define PMS_HD_FAIL(what, code) do { \
        if (err && errsz) { \
            if ((unsigned)(code) == 0x804101e2u) \
                snprintf(err, errsz, "this console could not look up the address - " \
                                     "load the shop again"); \
            else if (((unsigned)(code) & 0xFFFFFF00u) == 0x8095F000u) \
                snprintf(err, errsz, "this console refused the site's security certificate " \
                                     "(0x%x)", (unsigned)(code)); \
            else snprintf(err, errsz, "%s=0x%x", (what), (unsigned)(code)); \
        } \
        ret = -1; goto done; } while (0)

    if (host_unreachable_here(url)) {
        if (err && errsz)
            snprintf(err, errsz, "this console cannot reach that host - the release API's asset "
                                 "link has to be used instead");
        return -1;
    }

    /* What is already on disk, if anything. */
    if (stat(dest, &stt) == 0 && stt.st_size > 0) have = (long long)stt.st_size;

    /* ONE STACK AT A TIME - see g_tls_lock. A release check and a download both run on worker
       threads, so waiting here costs nothing; two stacks at once cost everything. */
    pthread_mutex_lock(&g_tls_lock);
    /* Same sizes as the check path - see the note there. */
    netmem = sceNetPoolCreate("pms-dl", 1024 * 1024, 0);
    if (netmem < 0) PMS_HD_FAIL("netpool", netmem);
    sslctx = sceSslInit(4 * 1024 * 1024);
    if (sslctx < 0) PMS_HD_FAIL("sslinit", sslctx);
    httpctx = sceHttpInit(netmem, sslctx, 4 * 1024 * 1024);
    if (httpctx < 0) PMS_HD_FAIL("httpinit", httpctx);
    tmpl = sceHttpCreateTemplate(httpctx, "PKG-MUTANT-SHOP", 1, 1);
    if (tmpl < 0) PMS_HD_FAIL("template", tmpl);
    /* An asset's API url answers 302 to the CDN, so redirects are not optional. */
    sceHttpSetAutoRedirect(tmpl, 1);
    /* WHAT MAKES TLS WORK HERE, all three of them - see tls_relax. */
    tls_relax(httpctx, tmpl, "download");
    sceHttpSetConnectTimeOut(tmpl, 30 * 1000 * 1000);
    sceHttpSetSendTimeOut(tmpl, 30 * 1000 * 1000);
    /* Per read, not per transfer: a 2 GB package legitimately takes many minutes. */
    sceHttpSetRecvTimeOut(tmpl, 60 * 1000 * 1000);
    conn = sceHttpCreateConnectionWithURL(tmpl, url, 1);
    if (conn < 0) PMS_HD_FAIL("connect", conn);
    req = sceHttpCreateRequestWithURL(conn, 0, url, 0);
    if (req < 0) PMS_HD_FAIL("request", req);
    /* THE BYTES, NOT THE DESCRIPTION. An asset's API url answers with the asset's JSON unless
       this header is present. Harmless for every other kind of URL this lane is handed. */
    sceHttpAddRequestHeader(req, "Accept", "application/octet-stream", 0);
    if (have > 0) {
        char rv[64];
        snprintf(rv, sizeof(rv), "bytes=%lld-", have);
        sceHttpAddRequestHeader(req, "Range", rv, 0);      /* 0 = overwrite, not append */
    }
    rc = sceHttpSendRequest(req, NULL, 0);
    if (rc < 0) PMS_HD_FAIL("send", rc);
    rc = sceHttpGetStatusCode(req, &status);
    if (rc < 0) PMS_HD_FAIL("status", rc);
    tls_verdict(1);                 /* the far end answered - see the note on the check path */
    if (status == 416 && have > 0) {
        /* Asked for bytes past the end: the whole file is already here. Not a failure - the same
           case the plain-HTTP lane learned to treat as success. */
        pms_dl_progress(have, have);
        ret = 0;
        goto done;
    }
    if (status != 200 && status != 206) {
        if (err && errsz) snprintf(err, errsz, "the server answered HTTP %d", status);
        ret = -1;
        goto done;
    }
    /* A 200 in answer to a Range request means the server ignored it, so what is on disk is not
       a prefix of what is arriving and must not be appended to. */
    if (have > 0 && status == 200) have = 0;

    {
        int flag = 0;
        unsigned long long cl64 = 0;
        if (sceHttpGetResponseContentLength(req, &flag, &cl64) >= 0 && cl64 > 0)
            clen = (long long)cl64;
    }
    pms_dl_progress(have, (clen > 0) ? have + clen : 0);

    mkparents(dest);
    fd = open(dest, O_WRONLY | O_CREAT | (have > 0 ? O_APPEND : O_TRUNC), 0777);
    if (fd < 0) PMS_HD_FAIL("open", errno);

    /* Heap, not stack: this runs on a worker thread with a bounded stack, and DL_BUF is the
       measured knee for read/write throughput on this kernel. */
    buf = (char *)malloc(DL_BUF);
    if (!buf) { if (err && errsz) snprintf(err, errsz, "out of memory"); ret = -1; goto done; }
    for (;;) {
        pms_dl_progress(have, -1);
        if (pms_dl_cancelled()) {
            if (err && errsz) snprintf(err, errsz, "canceled");
            ret = -2;
            goto done;
        }
        int n = sceHttpReadData(req, buf, DL_BUF);
        if (n == 0) break;                                   /* the body ended */
        if (n < 0) {
            if (err && errsz)
                snprintf(err, errsz, "the connection dropped at %lld bytes (0x%x)", have,
                         (unsigned)n);
            ret = -1;
            goto done;
        }
        if (write_all_checked(fd, buf, (size_t)n) != (ssize_t)n) {
            /* Do NOT keep counting. Advancing past bytes that were never stored is how a
               disk-full transfer used to finish "complete" and install a truncated package. */
            if (err && errsz)
                snprintf(err, errsz, "could not write to storage at %lld bytes (disk full?)",
                         have);
            ret = -1;
            goto done;
        }
        have += n;
    }
    close(fd);
    fd = -1;
    {
        long long want = pms_dl_expected();
        pms_dl_progress(have, -1);
        if (want > 0 && have < want) {
            if (err && errsz)
                snprintf(err, errsz, "short transfer: got %lld of %lld bytes", have, want);
            ret = -1;
            goto done;
        }
    }
    ret = 0;
#undef PMS_HD_FAIL
done:
    if (status <= 0) tls_verdict(0);
    if (fd >= 0) close(fd);
    if (buf) free(buf);
    if (req >= 0) sceHttpDeleteRequest(req);
    if (conn >= 0) sceHttpDeleteConnection(conn);
    if (tmpl >= 0) sceHttpDeleteTemplate(tmpl);
    if (httpctx >= 0) sceHttpTerm(httpctx);
    if (sslctx >= 0) sceSslTerm(sslctx);
    if (netmem >= 0) sceNetPoolDestroy(netmem);
    pthread_mutex_unlock(&g_tls_lock);
    return ret;
}

/* ---------------- A PROJECT THAT PUBLISHES SOMEWHERE OTHER THAN GITHUB --------------------
 * Given an index page and the link prefix that identifies a download on it, find the newest
 * version offered and the absolute URL for it.
 *
 *   key      "direct:https://pkg-zone.com/details/PKGI13337|/download/ps5/PKGI13337/"
 *   answer   tag "1.10.0", url ".../download/ps5/PKGI13337/1.10.0"
 *
 * THE PATTERN IS THE WHOLE PARSER. No HTML is interpreted: the prefix is searched for as plain
 * text and whatever follows it up to a quote, a '<', a '/' or whitespace is the version. That is
 * deliberately dumb - an HTML parser in a payload is a liability, and this has to survive a page
 * redesign rather than being clever about one. A link reading "latest" is skipped: it is an alias,
 * and recording it as the version we took would mean every later check compared "latest" against
 * "latest" and never saw a new release again.
 *
 * NEWEST BY NUMBER, not by position: pkg-zone lists newest first today, but so did GitHub's
 * /releases until it did not, and that cost this project a release. ver_cmp is the same comparison
 * the rest of this file uses for version strings.
 * ----------------------------------------------------------------------------------------- */
static int direct_version_newer(const char *a, const char *b) {
    /* "" loses to anything; otherwise the project's own numbering, compared as numbers. */
    if (!b || !b[0]) return 1;
    if (!a || !a[0]) return 0;
    return ver_cmp(a, b) > 0;
}

static int direct_latest(const char *index_url, const char *pattern,
                         char *tag, size_t tagsz, char *url, size_t urlsz,
                         char *buf, size_t bufsz, char *err, size_t errsz) {
    long long got = 0;
    if (tag && tagsz) tag[0] = 0;
    if (url && urlsz) url[0] = 0;
    if (!index_url || !index_url[0] || !pattern || !pattern[0]) {
        if (err && errsz) snprintf(err, errsz, "no download page was named");
        return -1;
    }
    /* TWO EXTRA TRIES. MEASURED on the host this was written for: every URL on it, its own root
       included, answering 500 with a 6,609-byte error page, then four consecutive 200s, then
       500 500 200 200 200 200 within one minute - it flaps, whatever the headers. github_releases deliberately does not retry, because an
       unauthenticated GitHub allowance is 60 calls an hour and retrying spends it; a project's own
       download page has no such allowance, and one blip would otherwise be cached as a failure
       for five minutes and reported to the owner as something to act on. */
    int st = 0;
    for (int attempt = 0; attempt < 4; attempt++) {
        if (attempt) sleep(2);
        st = https_get_text(index_url, buf, bufsz, &got, err, errsz);
        if (st == 200) break;
    }
    if (st != 200) {
        if (err && errsz && !err[0]) snprintf(err, errsz, "that page answered HTTP %d", st);
        return st > 0 ? st : -1;
    }
    if (got >= (long long)bufsz - 1) {
        if (err && errsz)
            snprintf(err, errsz, "that download page is larger than this console reads "
                                 "(%lld bytes)", got);
        return -2;
    }
    size_t plen = strlen(pattern);
    char best[64] = {0};
    const char *p = buf;
    for (int guard = 0; guard < 400; guard++) {
        const char *h = strstr(p, pattern);
        if (!h) break;
        const char *v = h + plen;
        char ver[64];
        size_t j = 0;
        while (v[j] && j < sizeof(ver) - 1) {
            char c = v[j];
            if (c == '"' || c == 0x27 || c == '<' || c == '>' || c == '/' || c == '?' ||
                c == '#' || c == '&' || c == ' ' || c == '\t' || c == '\r' || c == '\n') break;
            ver[j] = c;
            j++;
        }
        ver[j] = 0;
        p = v;
        if (!ver[0]) continue;
        if (!strcasecmp(ver, "latest")) continue;       /* an alias, not a version */
        /* A version is digits, dots and letters. Anything else is not a link to a build. */
        int okv = 1;
        for (size_t k = 0; ver[k]; k++) {
            char c = ver[k];
            if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') ||
                  (c >= 'A' && c <= 'Z') || c == '.' || c == '-' || c == '_')) { okv = 0; break; }
        }
        if (!okv) continue;
        if (direct_version_newer(ver, best)) snprintf(best, sizeof(best), "%s", ver);
    }
    if (!best[0]) {
        if (err && errsz) snprintf(err, errsz, "that page lists no version of this download");
        return -2;
    }
    snprintf(tag, tagsz, "%s", best);
    /* The absolute URL, built from the index's own scheme and host so nothing here has to be told
       the host twice. The pattern is an absolute path on that host, which is how it is written. */
    {
        const char *sch = index_url;
        const char *hs = strstr(index_url, "://");
        if (!hs) { if (err && errsz) snprintf(err, errsz, "that download page is not a url"); return -2; }
        const char *he = strchr(hs + 3, '/');
        size_t hostlen = he ? (size_t)(he - sch) : strlen(sch);
        if (hostlen + plen + strlen(best) + 1 >= urlsz) {
            if (err && errsz) snprintf(err, errsz, "that download address is too long");
            return -2;
        }
        memcpy(url, sch, hostlen);
        url[hostlen] = 0;
        snprintf(url + hostlen, urlsz - hostlen, "%s%s", pattern, best);
    }
    return 200;
}

static int direct_key_split(const char *key, char *idx, size_t idxsz, char *pat, size_t patsz) {
    if (!key || strncmp(key, "direct:", 7)) return 0;
    const char *bar = strchr(key + 7, '|');
    if (!bar || bar == key + 7 || !bar[1]) return 0;
    size_t n = (size_t)(bar - (key + 7));
    if (n >= idxsz) return 0;
    memcpy(idx, key + 7, n);
    idx[n] = 0;
    snprintf(pat, patsz, "%s", bar + 1);
    /* The index has to be an https page and the pattern an absolute path on it. Both come from
       the catalogue through a query string, so both are checked here rather than trusted. */
    if (strncmp(idx, "https://", 8) && strncmp(idx, "http://", 7)) return 0;
    if (pat[0] != '/' || strstr(pat, "..")) return 0;
    return 1;
}

static void dl_drop_same_stem(const char *final_path) {
    char dir[700], base[300], stem[128];
    snprintf(dir, sizeof(dir), "%s", final_path);
    char *sl = strrchr(dir, '/');
    if (!sl) return;
    *sl = 0;
    snprintf(base, sizeof(base), "%s", sl + 1);
    pms_file_stem(base, stem, sizeof(stem));
    if (!stem[0] || !dir[0]) return;
    DIR *d = opendir(dir);
    if (!d) return;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        if (de->d_name[0] == '.') continue;
        if (!strcmp(de->d_name, base)) continue;        /* the file we just put there */
        if (pms_name_is_bundled(de->d_name)) continue;  /* this build's own copy */
        char other[128];
        pms_file_stem(de->d_name, other, sizeof(other));
        if (!other[0] || strcmp(other, stem)) continue;
        char victim[900];
        snprintf(victim, sizeof(victim), "%s/%s", dir, de->d_name);
        if (unlink(victim) == 0) ilog("fetch: removed the previous %s (%s)", stem, de->d_name);
    }
    closedir(d);
}

/* ---- which release this console took, written down beside the file ----------------------
 * Without this the panel compares the CATALOGUE's version - the version the machine that BUILT
 * the catalogue was holding - so a payload updated on the console went on being offered the same
 * update for ever, and pressing Update fetched the same bytes again.
 *
 * ONE NOTE PER STEM, dot-prefixed: a newer release overwrites it rather than leaving a stale one
 * beside the new file, and every directory walk here skips dotfiles - which is also why the note
 * can never be mistaken for a payload.
 *
 * It is also the only honest evidence that THIS lane put a file in the folder, as opposed to a
 * copy some PC left there earlier. /api/payloads/load needs exactly that: see the note there. */
static void dl_note_path(const char *dir, const char *name, char *out, size_t outsz) {
    char stem[128];
    out[0] = 0;
    pms_file_stem(name, stem, sizeof(stem));
    if (!stem[0] || !dir || !dir[0]) return;
    snprintf(out, outsz, "%s/.%s.ver", dir, stem);
}

static void dl_take_note(const char *dir, const char *name, const char *tag) {
    char p[800];
    if (!tag || !tag[0]) return;
    dl_note_path(dir, name, p, sizeof(p));
    if (!p[0]) return;
    int f = open(p, O_WRONLY | O_CREAT | O_TRUNC, 0777);
    if (f < 0) return;
    (void)write_all_checked(f, tag, strlen(tag));
    close(f);
}

/* The release recorded for this file's stem, or "" when this lane never fetched one. */
static void dl_taken_version(const char *dir, const char *name, char *out, size_t outsz) {
    char p[800];
    out[0] = 0;
    dl_note_path(dir, name, p, sizeof(p));
    if (!p[0]) return;
    int f = open(p, O_RDONLY);
    if (f < 0) return;
    ssize_t r = read(f, out, outsz - 1);
    close(f);
    if (r <= 0) { out[0] = 0; return; }
    out[r] = 0;
    /* A tag is one line; refuse anything that is not plainly one. */
    for (size_t i = 0; out[i]; i++)
        if (out[i] < 0x20 || out[i] == 0x7F) { out[i] = 0; break; }
}

static const char *json_obj_end(const char *p) {
    if (!p || *p != '{') return NULL;
    int depth = 0, instr = 0;
    for (const char *q = p; *q; q++) {
        if (instr) {
            if (*q == 0x5C && q[1]) { q++; continue; }
            if (*q == '"') instr = 0;
            continue;
        }
        if (*q == '"') { instr = 1; continue; }
        if (*q == '{') depth++;
        else if (*q == '}') { depth--; if (depth == 0) return q + 1; }
    }
    return NULL;
}

static const char *release_choose(const char *json, const char **endp) {
    const char *p = json;
    *endp = NULL;
    if (!p) return NULL;
    while (*p && *p != '[' && *p != '{') p++;
    if (*p == '{') { *endp = json_obj_end(p); return *endp ? p : NULL; }
    if (*p != '[') return NULL;
    p++;
    const char *best = NULL, *best_end = NULL;
    char best_key[40];
    best_key[0] = 0;
    for (;;) {
        while (*p == ' ' || *p == 0x0A || *p == 0x0D || *p == 0x09 || *p == ',') p++;
        if (*p != '{') break;
        const char *e = json_obj_end(p);
        if (!e) break;
        int is_draft = 0;
        const char *dr = strstr(p, "\"draft\"");
        if (dr && dr < e) {
            dr += 7;
            while (*dr == ' ' || *dr == ':') dr++;
            is_draft = !strncmp(dr, "true", 4);
        }
        if (!is_draft) {
            char key[40];
            key[0] = 0;
            json_str_after_lim(p, e, "published_at", key, sizeof(key));
            if (!key[0]) json_str_after_lim(p, e, "created_at", key, sizeof(key));
            if (!best || (key[0] && strcmp(key, best_key) > 0)) {
                best = p;
                best_end = e;
                snprintf(best_key, sizeof(best_key), "%s", key);
            }
        }
        p = e;
    }
    if (!best) return NULL;
    *endp = best_end;
    return best;
}

static int github_releases(const char *repo, char *buf, size_t bufsz, char *err, size_t errsz) {
    char api[320];
    long long got = 0;
    snprintf(api, sizeof(api), "https://api.github.com/repos/%s/releases?per_page=3", repo);
    int st = https_get_text(api, buf, bufsz, &got, err, errsz);
    if (st == 200 && got >= (long long)bufsz - 1) {
        if (err && errsz)
            snprintf(err, errsz, "that project's release page is larger than this console reads "
                                 "(%lld bytes)", got);
        return -2;
    }
    return st;
}

static int release_assets(const char *json, const char *end, up_asset_t *out, int max) {
    int n = 0;
    const char *p = strstr(json, "\"assets\"");
    if (!p || (end && p >= end)) return 0;
    /* The name, size, digest and API url all sit BEFORE browser_download_url inside each asset
       object, so the window for them runs FORWARD from the previous asset's url (or the start of
       the array) up to this one. Walking BACK to the nearest '{' - what this did at first - lands
       inside the asset's own nested "uploader" object, and every field came back empty. */
    const char *win = p;
    while (n < max && (p = strstr(p, "\"browser_download_url\"")) != NULL) {
        if (end && p >= end) break;
        const char *cur = p;
        char dg[128] = {0};
        up_asset_t a;
        memset(&a, 0, sizeof(a));
        /* Bare key names: the json_* helpers add the quotes themselves - passing them already
           quoted made every lookup search for """name""" and find nothing. The FIRST "url" in
           the window is the asset's own; it precedes the uploader object, which has one too. */
        json_str_after_lim(win, cur, "name", a.name, sizeof(a.name));
        json_str_after_lim(win, cur, "url", a.url, sizeof(a.url));
        json_str_after_lim(win, cur, "digest", dg, sizeof(dg));
        if (!strncasecmp(dg, "sha256:", 7)) snprintf(a.digest, sizeof(a.digest), "%s", dg + 7);
        {
            const char *sp = strstr(win, "\"size\"");
            a.size = (sp && sp < cur) ? (long long)json_num_after(sp, "size", 0) : 0;
        }
        if (a.name[0] && a.url[0]) out[n++] = a;
        p = cur + 1;
        win = cur + 1;
    }
    return n;
}

/* Caller holds g_up_lock. */
static upstream_t *up_find(const char *repo) {
    for (int i = 0; i < UP_MAX; i++)
        if (g_up[i].repo[0] && !strcmp(g_up[i].repo, repo)) return &g_up[i];
    return NULL;
}

static upstream_t *up_slot(const char *repo) {
    upstream_t *e = up_find(repo);
    if (e) return e;
    upstream_t *best = &g_up[0];
    for (int i = 0; i < UP_MAX; i++) {
        if (!g_up[i].repo[0]) { best = &g_up[i]; break; }
        if (g_up[i].at < best->at) best = &g_up[i];
    }
    memset(best, 0, sizeof(*best));
    snprintf(best->repo, sizeof(best->repo), "%s", repo);
    return best;
}

static void *upstream_worker(void *arg) {
    (void)arg;
    char *json = (char *)malloc(GH_BUF_BYTES);
    for (;;) {
        char repo[160] = {0};
        pthread_mutex_lock(&g_up_lock);
        if (g_up_qn <= 0 || !json) {
            g_up_busy = 0;
            pthread_mutex_unlock(&g_up_lock);
            break;
        }
        snprintf(repo, sizeof(repo), "%s", g_up_q[0]);
        for (int i = 1; i < g_up_qn; i++) memcpy(g_up_q[i - 1], g_up_q[i], sizeof(g_up_q[0]));
        g_up_qn--;
        pthread_mutex_unlock(&g_up_lock);

        upstream_t r;
        memset(&r, 0, sizeof(r));
        snprintf(r.repo, sizeof(r.repo), "%s", repo);
        char err[200] = {0};
        int st = 0;
        /* A DIRECT SOURCE TAKES THE SAME LANE. Same queue, same cache, same six hours, same
           pending protocol - the page must not have to know which kind of project this is, and
           the only thing that differs is where the answer is read from. The result is one asset,
           because a direct source publishes one file per console and the URL already says which.
           It carries no published checksum (pkg-zone sends content-length and last-modified and
           no hash), so `digest` stays empty and the transfer is checked against Content-Length
           alone - the same position every payload without a release digest is already in. */
        char didx[200] = {0}, dpat[120] = {0};
        if (direct_key_split(repo, didx, sizeof(didx), dpat, sizeof(dpat))) {
            char durl[320] = {0};
            int dst = direct_latest(didx, dpat, r.tag, sizeof(r.tag), durl, sizeof(durl),
                                    json, GH_BUF_BYTES, err, sizeof(err));
            if (dst == 200 && r.tag[0] && durl[0]) {
                snprintf(r.page, sizeof(r.page), "%s", didx);
                /* The filename the console should land it under. The URL's own tail is the
                   version ("1.10.0"), which is not a package name - and both fetch routes fall
                   back to the URL tail when no name is given, so a file called "1.10.0" would
                   then be refused by the installer for not ending .pkg. The pattern names the
                   platform and the id, so the name is built from those. */
                const char *seg = dpat;
                char a1[40] = {0}, a2[40] = {0};
                {   /* "/download/ps5/PKGI13337/" -> a1 "ps5", a2 "PKGI13337" */
                    const char *s1 = strchr(seg + 1, '/');
                    const char *s2 = s1 ? strchr(s1 + 1, '/') : NULL;
                    const char *s3 = s2 ? strchr(s2 + 1, '/') : NULL;
                    if (s1 && s2 && (size_t)(s2 - s1 - 1) < sizeof(a1)) {
                        memcpy(a1, s1 + 1, (size_t)(s2 - s1 - 1));
                        a1[s2 - s1 - 1] = 0;
                    }
                    if (s2 && s3 && (size_t)(s3 - s2 - 1) < sizeof(a2)) {
                        memcpy(a2, s2 + 1, (size_t)(s3 - s2 - 1));
                        a2[s3 - s2 - 1] = 0;
                    }
                }
                for (char *c = a1; *c; c++) if (*c >= 'a' && *c <= 'z') *c = (char)(*c - 32);
                if (a1[0] && a2[0])
                    snprintf(r.a[0].name, sizeof(r.a[0].name), "%s_%s_v%s.pkg", a1, a2, r.tag);
                else
                    snprintf(r.a[0].name, sizeof(r.a[0].name), "%s.pkg", r.tag);
                snprintf(r.a[0].url, sizeof(r.a[0].url), "%s", durl);
                r.a[0].size = 0;                    /* not published; Content-Length decides */
                r.na = 1;
            } else if (!r.error[0]) {
                snprintf(r.error, sizeof(r.error), "%s",
                         err[0] ? err : "that download page could not be read");
            }
            goto store;
        }
        st = github_releases(repo, json, GH_BUF_BYTES, err, sizeof(err));
        if (st == 200) {
            const char *end = NULL;
            const char *rel = release_choose(json, &end);
            if (!rel) {
                /* A project can have tags and no releases at all. Say so plainly rather than
                   reporting an empty version, which reads as "up to date". */
                snprintf(r.error, sizeof(r.error), "no releases");
            } else {
                char pub[40] = {0};
                json_str_after_lim(rel, end, "tag_name", r.tag, sizeof(r.tag));
                json_str_after_lim(rel, end, "html_url", r.page, sizeof(r.page));
                json_str_after_lim(rel, end, "published_at", pub, sizeof(pub));
                snprintf(r.published, sizeof(r.published), "%.10s", pub);
                const char *pr = strstr(rel, "\"prerelease\"");
                if (pr && pr < end) {
                    pr += 12;
                    while (*pr == ' ' || *pr == ':') pr++;
                    r.prerelease = !strncmp(pr, "true", 4);
                }
                /* What the project itself calls stable, when that is a different release - the
                   panel says which, and /releases/latest hiding pre-releases is what started all
                   of this. */
                if (r.prerelease) {
                    const char *p2 = end;
                    for (int guard = 0; guard < UP_MAX && p2 && *p2; guard++) {
                        const char *e2 = NULL;
                        const char *r2 = release_choose(p2, &e2);
                        if (!r2 || !e2) break;
                        const char *q2 = strstr(r2, "\"prerelease\"");
                        int pre2 = 1;
                        if (q2 && q2 < e2) {
                            q2 += 12;
                            while (*q2 == ' ' || *q2 == ':') q2++;
                            pre2 = !strncmp(q2, "true", 4);
                        }
                        if (!pre2) {
                            json_str_after_lim(r2, e2, "tag_name",
                                               r.stable_tag, sizeof(r.stable_tag));
                            break;
                        }
                        p2 = e2;
                    }
                }
                r.na = release_assets(rel, end, r.a, UP_ASSETS);
            }
        } else if (st == 403 || st == 429) {
            snprintf(r.error, sizeof(r.error), "rate-limited");
        } else if (st == 404) {
            snprintf(r.error, sizeof(r.error), "not visible");
        } else if (st == -2) {
            snprintf(r.error, sizeof(r.error), "%s", err);
        } else {
            snprintf(r.error, sizeof(r.error), "%s", err[0] ? err : "could not reach GitHub");
        }
store:;   /* a null statement: a label must be followed by one, and C99 does not count a declaration */
        /* Keep the document so the route can pick an asset per item without asking again. */
        pthread_mutex_lock(&g_up_lock);
        upstream_t *slot = up_slot(repo);
        char keep[160];
        snprintf(keep, sizeof(keep), "%s", slot->repo);
        *slot = r;
        snprintf(slot->repo, sizeof(slot->repo), "%s", keep);
        /* A FAILURE IS CACHED TOO, BRIEFLY. Without it a panel that polls while GitHub is
           refusing keeps asking and keeps being refused for the rest of the hour. */
        slot->at = (long long)time(NULL) - (r.error[0] ? (UP_TTL_S - 300) : 0);
        pthread_mutex_unlock(&g_up_lock);
    }
    if (json) free(json);
    return NULL;
}

/* Caller holds g_up_lock. Put a project in the queue unless it is already there. */
static void up_enqueue(const char *repo) {
    for (int i = 0; i < g_up_qn; i++) if (!strcmp(g_up_q[i], repo)) return;
    if (g_up_qn >= UP_MAX) return;
    snprintf(g_up_q[g_up_qn], sizeof(g_up_q[0]), "%s", repo);
    g_up_qn++;
    if (!g_up_busy) {
        pthread_t t;
        pthread_attr_t a;
        pthread_attr_init(&a);
        pthread_attr_setstacksize(&a, 512 * 1024);
        if (pthread_create(&t, &a, upstream_worker, NULL) == 0) {
            pthread_detach(t);
            g_up_busy = 1;
        }
        pthread_attr_destroy(&a);
    }
}
